module.exports = function(RED) {
    "use strict";

    function MeoEventNode(n) {
        RED.nodes.createNode(this, n);
        var node = this;
        node.edge = RED.nodes.getNode(n.edge);
        node.device = n.device;
        // Cap key; "" means any.
        node.cap = typeof n.cap === "string" ? n.cap : "";

        if (!node.edge) {
            node.status({ fill: "red", shape: "ring", text: "node-red:meo.errors.noEdge" });
            return;
        }
        if (!node.device) {
            node.status({ fill: "red", shape: "ring", text: "node-red:meo.errors.noDevice" });
            return;
        }

        // The subscription is shared by every event node, so filtering is ours.
        node.onDeviceEvent = function(deviceId, cap, value) {
            if (deviceId !== node.device) { return; }
            if (node.cap && cap !== node.cap) { return; }

            node.send({
                payload: value,
                // Cap key, not the MQTT topic — flows never see topics.
                topic: cap,
                deviceId: deviceId,
                cap: cap
            });
            node.status({ fill: "green", shape: "dot", text: cap + ": " + value });
        };

        node.edge.registerListener(node);

        node.on("close", function(removed, done) {
            node.edge.deregisterListener(node, done);
        });
    }

    RED.nodes.registerType("meo-event", MeoEventNode);
};
